import re, subprocess, difflib

def statements(text):
    out = {}
    for name, slug, stmt in re.findall(r"^## ([^\n]+?) \(`([^\n`]+)`\)\n\n\*\*Statement\.\*\*\s*(.*?)(?=\n\n\*\*)", text, re.S | re.M):
        norm = " ".join(re.sub(r"^\s*- ", "", stmt, flags=re.M).split())
        out[slug] = norm
    return out

for path in ["basis/principles.md", "basis/architecture-principles.md"]:
    old = subprocess.run(["git", "show", f"HEAD:{path}"], capture_output=True, text=True).stdout
    new = open(path).read()
    o, n = statements(old), statements(new)
    print(f"== {path}: {len(o)} -> {len(n)} principles")
    for slug in o:
        if o[slug] == n.get(slug):
            continue
        print(f"-- {slug}:")
        sm = difflib.SequenceMatcher(None, o[slug].split(), n[slug].split())
        for tag, i1, i2, j1, j2 in sm.get_opcodes():
            if tag != "equal":
                print(f"   {tag}: {' '.join(o[slug].split()[i1:i2])!r} -> {' '.join(n[slug].split()[j1:j2])!r}")
EOF

